css:
.print-format {
    padding: 5mm;
}

.print-format h1,
.print-format h2,
.print-format h3,
.print-format h4,
.print-format h5 {
    margin: 0;
    font-size: 10pt;
}

.print-format .w-full {
    width: 100%;
}

.print-format .w-1\/2 {
    width: 50%;
    min-width: 50%;
    max-width: 50%;
}

.print-format .w-1\/4 {
    width: 25%;
    min-width: 25%;
    max-width: 25%;
}

.print-format .h-full {
    height: 100%;
}

.print-format .h-2 {
    height: 1rem;
}

.print-format .h-4 {
    height: 2rem;
}

.print-format .min-h-4 {
    height: 2rem;
}

.print-format .p-4 {
    padding: 1rem;
}

.print-format .p-1 {
    padding: 0.5rem !important;
}

.print-format .p-2 {
    padding: 0.5rem !important;
}

.print-format .py-2 {
    padding-top: 0.5rem !important;
    padding-bottom: 0.5rem !important;
}

.print-format .pt-4 {
    padding-top: 1rem !important;
    padding-bottom: 1rem !important;
}

.print-format .fs-base {
    font-size: 13px !important;
}

.print-format .m-0,
.m-0:not(.section-break) {
    margin: 0 !important;
}

.print-format .mt-0,
.mt-0:not(.section-break) {
    margin-top: 0 !important;
}

.print-format .mb-0 {
    margin-bottom: 0 !important;
}

.print-format .mb-2 {
    margin-bottom: 0.5rem !important;
}

.print-format .mb-4 {
    margin-bottom: 1rem !important;
}

.print-format .mt-2 {
    margin-top: 0.5rem !important;
}

.print-format .mt-4 {
    margin-top: 1rem !important;
}

.print-format .mt-8 {
    margin-top: 2rem !important;
}

.print-format .border {
    border: 1px solid black;
}

.print-format .border-0 {
    border: none !important;
}

.print-format .border-black {
    border-color: black !important;
}

.print-format .border-end {
    border-right: 1px solid black;
}

.print-format .border-end-0 {
    border-right: none !important;
}

.print-format .border-start-0 {
    border-left: none !important;
}

.print-format .border-top-0 {
    border-top: none !important;
}

.print-format .fw-bold {
    font-weight: bold !important;
}

.print-format .title-text {
    font-weight: 900;
    text-align: center;
    font-size: 1rem;
}

.print-format .page-heading {
    font-weight: 900;
}

.print-format .diagnosis-col {
    width: 20%;
}

.print-format .ql-editor {
    color: black;
}

.print-format .row:not(.section-break) {
    margin-top: 0 !important;
}

.print-format .table-title-col-20 {
    width: 20%;
    font-weight: bold;
}

.print-format .table-title-col-30 {
    width: 30%;
    font-weight: bold;
}

.print-format .flex {
    display: flex;
}

.print-format .flex-col {
    flex-direction: column;
}

.print-format .space-between {
    justify-content: space-between;
}

.print-format .flex-wrap {
    flex-wrap: wrap;
}

.print-format .gap-4 {
    gap: 1rem;
}

.print-format .grid {
    display: grid;
}

.print-format .grid-cols-2 {
    grid-template-columns: repeat(2, 1fr);
}

.print-format .grid-cols-4 {
    grid-template-columns: repeat(4, 1fr);
}

.print-format .result-grid {
    background: black;
    gap: 1px;
}

.print-format .result-grid>div {
    background: white;
}

.print-format .print-logo {
    padding: 2mm;
    width: 30mm;
    min-width: 30mm;
    max-width: 30mm;
    height: auto;
}

.print-format .flex-grow {
    flex-grow: 1;
}
